import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

import { tv, type VariantProps } from "tailwind-variants";

export const buttonStyles = tv({
  base: "inline-flex shrink-0 cursor-default items-center justify-center gap-2 whitespace-nowrap rounded-md font-medium tracking-[-0.01em] data-[disabled]:cursor-default data-[disabled]:opacity-50 data-[disabled]:shadow-none data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-3 data-[focus-visible]:outline-ring",
  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-[var(--shadow-card)] hover:bg-primary/90 data-[pressed]:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground hover:bg-border/70 data-[pressed]:bg-border/70",
      outline:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted data-[pressed]:bg-muted",
      ghost:
        "text-foreground hover:bg-muted data-[pressed]:bg-muted aria-[pressed=true]:bg-accent aria-[pressed=true]:text-accent-foreground aria-[pressed=true]:hover:bg-accent",
      minimal:
        "text-muted-foreground hover:bg-muted hover:text-foreground data-[pressed]:bg-muted data-[pressed]:text-foreground",
      destructive:
        "bg-destructive text-background shadow-[var(--shadow-card)] hover:bg-destructive/90 data-[pressed]:bg-destructive/90",
    },
    size: {
      default: "h-11 px-5 text-sm",
      sm: "h-9 px-3.5 text-sm",
      lg: "h-12 px-6 text-sm",
      icon: "size-11 cursor-pointer p-0",
    },
  },
  defaultVariants: { variant: "default", size: "default" },
});

export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;
export type ButtonSize = NonNullable<VariantProps<typeof buttonStyles>["size"]>;

"use client";

import { type MotionProps, motion, useReducedMotion } from "motion/react";
import {
  Button as AriaButton,
  type ButtonProps as AriaButtonProps,
  composeRenderProps,
} from "react-aria-components";
import {
  type ButtonSize,
  type ButtonVariant,
  buttonStyles,
} from "./button-styles";

export interface ButtonProps
  extends Omit<
    AriaButtonProps,
    | "style"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
    | "onHoverStart"
    | "onHoverEnd"
  > {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: ButtonSize;
  static?: boolean;
  layout?: MotionProps["layout"];
}

const MotionButton = motion.create(AriaButton);

export function Button({
  className,
  variant = "default",
  size = "default",
  static: isStatic = false,
  layout,
  ...props
}: ButtonProps) {
  const reduceMotion = useReducedMotion();
  return (
    <MotionButton
      data-slot="button"
      data-variant={variant}
      data-size={size}
      layout={reduceMotion ? false : layout}
      whileHover={
        isStatic || reduceMotion || props.isDisabled
          ? undefined
          : { scale: 1.015 }
      }
      whileTap={
        isStatic || reduceMotion || props.isDisabled
          ? undefined
          : { scale: 0.96 }
      }
      transition={{ type: "spring", stiffness: 500, damping: 36 }}
      className={composeRenderProps(className, (className) =>
        buttonStyles({ variant, size, className }),
      )}
      {...props}
    />
  );
}

"use client";

import {
  animate,
  motion,
  useInView,
  useMotionValue,
  useReducedMotion,
} from "motion/react";
import { type ComponentProps, useEffect, useRef, useState } from "react";
import { cn } from "./utils";
import { Button } from "./button";

export interface MarqueeProps extends ComponentProps<"div"> {
  speed?: number;
}

export function Marquee({
  speed = 50,
  children,
  className,
  ...props
}: MarqueeProps) {
  const viewport = useRef<HTMLDivElement>(null);
  const firstCopy = useRef<HTMLDivElement>(null);
  const controls = useRef<ReturnType<typeof animate> | null>(null);
  const [width, setWidth] = useState(0);
  const [viewportWidth, setViewportWidth] = useState(0);
  const [paused, setPaused] = useState(false);
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  const inView = useInView(viewport);
  const reducedMotion = useReducedMotion();
  const x = useMotionValue(0);

  useEffect(() => {
    if (!firstCopy.current) return;
    const copy = firstCopy.current;
    const observer = new ResizeObserver(() => {
      setViewportWidth(viewport.current?.clientWidth ?? 0);
      setWidth(copy.offsetWidth);
    });
    observer.observe(copy);
    if (viewport.current) observer.observe(viewport.current);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!width || speed <= 0 || reducedMotion) {
      x.set(0);
      return;
    }
    x.set(0);
    const animation = animate(x, [0, -width], {
      duration: width / speed,
      ease: "linear",
      repeat: Infinity,
    });
    controls.current = animation;
    return () => {
      animation.stop();
      controls.current = null;
    };
  }, [reducedMotion, speed, width, x]);

  useEffect(() => {
    if (!width) return;
    if (paused || hovered || focused || !inView) controls.current?.pause();
    else controls.current?.play();
  }, [focused, hovered, inView, paused, width]);

  return (
    <div {...props} data-slot="marquee" className={cn("grid gap-3", className)}>
      <div
        ref={viewport}
        className="overflow-hidden"
        onPointerEnter={() => setHovered(true)}
        onPointerLeave={() => setHovered(false)}
        onFocusCapture={() => setFocused(true)}
        onBlurCapture={(event) => {
          if (!event.currentTarget.contains(event.relatedTarget))
            setFocused(false);
        }}
      >
        <motion.div className="flex w-max" style={{ x }}>
          <div
            ref={firstCopy}
            style={{ minWidth: viewportWidth }}
            className="flex shrink-0 items-center gap-6 pr-6"
          >
            {children}
          </div>
          <div
            aria-hidden="true"
            inert
            style={{ minWidth: viewportWidth }}
            className="flex shrink-0 items-center gap-6 pr-6 motion-reduce:hidden"
          >
            {children}
          </div>
        </motion.div>
      </div>
      {speed > 0 && (
        <div className="flex justify-start motion-reduce:hidden">
          <Button
            size="sm"
            variant="secondary"
            onPress={() => setPaused((current) => !current)}
          >
            {paused ? "Play motion" : "Pause motion"}
          </Button>
        </div>
      )}
    </div>
  );
}
